  })

  test('scenario 2 — card cross-lane move persists after reload', async ({ page, request }) => {
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `DnD Cross-Lane Board ${Date.now()}` },
    })
